describe('Sticky Header Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('macbook-15');
  });

  it('should keep header visible when scrolling down the page', () => {
    // Get initial header position
    cy.get('header').should('be.visible');
    const initialHeaderTop = cy.get('header').then($header => {
      return $header[0].getBoundingClientRect().top;
    });

    // Scroll down significantly
    cy.scrollTo(0, 500);

    // Verify header is still visible and at top of viewport
    cy.get('header').should('be.visible');
    cy.get('header').then($header => {
      const headerTop = $header[0].getBoundingClientRect().top;
      expect(headerTop).to.be.lessThan(100);
    });

    // Verify header has sticky positioning applied
    cy.get('header').should('have.css', 'position', 'sticky').or('have.css', 'position', 'fixed');
  });

  it('should maintain header visibility during continuous scrolling', () => {
    cy.get('header').should('be.visible');

    // Scroll to middle of page
    cy.scrollTo(0, 1000);
    cy.get('header').should('be.visible');

    // Continue scrolling down
    cy.scrollTo(0, 2000);
    cy.get('header').should('be.visible');

    // Scroll back to top
    cy.scrollTo(0, 0);
    cy.get('header').should('be.visible');
  });

  it('should handle header with dynamic content and maintain sticky behavior', () => {
    cy.get('header').should('exist');

    // Verify header contains expected navigation elements
    cy.get('header nav').should('be.visible');
    cy.get('header a').should('have.length.greaterThan', 0);

    // Scroll and verify nav items remain accessible
    cy.scrollTo(0, 800);
    cy.get('header nav a').first().should('be.visible');
    cy.get('header nav a').first().should('not.have.css', 'display', 'none');
  });

  it('should not overlap page content when sticky', () => {
    cy.get('header').then($header => {
      const headerHeight = $header.outerHeight();

      // Scroll down
      cy.scrollTo(0, 500);

      // Get first content element below header
      cy.get('main').then($main => {
        const mainTop = $main[0].getBoundingClientRect().top;
        // Main content should start below header
        expect(mainTop).to.be.greaterThanOrEqual(headerHeight);
      });
    });
  });

  it('should handle sticky header on mobile viewport', () => {
    cy.viewport('iphone-x');
    cy.get('header').should('be.visible');

    cy.scrollTo(0, 300);
    cy.get('header').should('be.visible');

    // Verify header doesn't take excessive space on mobile
    cy.get('header').then($header => {
      const headerHeight = $header.outerHeight();
      expect(headerHeight).to.be.lessThan(150);
    });
  });

  it('should maintain z-index to appear above other content', () => {
    cy.scrollTo(0, 500);

    cy.get('header').then($header => {
      const headerZIndex = window.getComputedStyle($header[0]).zIndex;
      expect(parseInt(headerZIndex)).to.be.greaterThan(0);
    });

    // Verify header is clickable and not hidden behind content
    cy.get('header a').first().should('be.visible').click({ force: false });
  });

  it('should handle rapid scroll events without losing sticky behavior', () => {
    cy.get('header').should('be.visible');

    // Rapid scroll down
    cy.scrollTo(0, 100);
    cy.scrollTo(0, 200);
    cy.scrollTo(0, 300);
    cy.scrollTo(0, 400);

    cy.get('header').should('be.visible');

    // Rapid scroll up
    cy.scrollTo(0, 200);
    cy.scrollTo(0, 100);
    cy.scrollTo(0, 0);

    cy.get('header').should('be.visible');
  });

  it('should preserve header functionality when sticky', () => {
    cy.scrollTo(0, 600);

    // Test header links are functional
    cy.get('header a').first().should('be.visible').and('not.be.disabled');

    // Test header buttons if present
    cy.get('header button').each($button => {
      cy.wrap($button).should('be.visible').and('not.be.disabled');
    });
  });
});
